/* =========================================
   Advanced Responsive: Tablet & Desktop
   ========================================= */
@media (min-width: 901px) {
  .container {
    display: grid;
    grid-template-columns: 1fr minmax(340px, 680px) 1fr;
    gap: 0px;
    justify-items: center;
    align-items: flex-start;
    padding-left: 4vw;
    padding-right: 4vw;
  }
  .main-content {
    grid-column: 2 / 3;
    width: 100%;
  }
  .tool-card, .suggestion-card {
    margin-left: 0; margin-right: 0;
    max-width: 510px;
    border-radius: 22px;
    box-shadow: 0 11px 34px 0 rgba(27,35,68,0.15), 0 0 0 1.7px var(--border-color, #24244d);
  }
}

/* Typographical scaling for large screens */
@media (min-width: 1101px) {
  html { font-size: 18px; }
  .title, .home-title { font-size: 2.44rem; }
  .signin-title, .subtitle { font-size: 1.17rem; }
